 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const specColors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const ink = specColors.ink;
  const paper = specColors.paper;
  const accent = specColors.accent;
  const surface = specColors.surface;

  const atlasWidth = 512;
  const atlasHeight = 320;
  const cardWidth = 0.8;
  const cardHeight = cardWidth * (atlasHeight / atlasWidth);

  const root = new Group();
  const cardGroup = new Group();
  root.add(cardGroup);

  const fallbackGradient = mix(color(surface), color(ink), smoothstep(0.0, 1.0, uv().y));

  const backGeo = new PlaneGeometry(cardWidth * 1.25, cardHeight * 1.35);
  const backMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  backMat.colorNode = fallbackGradient;
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.z = -0.04;
  cardGroup.add(backMesh);

  const edgeOpacity = uniform(0.0);
  const edgeGeo = new PlaneGeometry(cardWidth + 0.06, cardHeight + 0.06);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    side: THREE.DoubleSide,
  });
  edgeMat.opacityNode = edgeOpacity;
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.002;
  cardGroup.add(edgeMesh);

  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  cardMat.colorNode = fallbackGradient;
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardGroup.add(cardMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      loadedTexture = tex;
      cardMat.colorNode = texture(tex, uv());
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((i) => i.role === 'headline') ?? items[0];
  const textString = textItem?.text ?? 'Journal 3';
  const fontSize = textItem?.typography?.fontSize ?? 39;

  const label = ctx.fontAtlas.createText(textString, {
    fontSize,
    color: paper,
    align: 'center',
  });
  label.position.set(0, 0, 0.005);
  cardGroup.add(label);

  root.userData.handlers = {};

  let hovering = false;
  let pressing = false;
  const activeTweens = [];

  const killCardTweens = () => {
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.scale);
    gsap.killTweensOf(edgeOpacity);
  };

  const animateHover = (isIn) => {
    killCardTweens();
    const lift = isIn ? 0.15 : 0.0;
    const scale = isIn ? 1.02 : 1.0;
    activeTweens.push(
      gsap.to(cardGroup.position, { z: lift, duration: 0.35, ease: 'power2.out' })
    );
    activeTweens.push(
      gsap.to(cardGroup.scale, { x: scale, y: scale, z: scale, duration: 0.35, ease: 'power2.out' })
    );
    activeTweens.push(
      gsap.to(edgeOpacity, { value: isIn ? 0.9 : 0.0, duration: 0.25, ease: 'power2.out' })
    );
  };

  root.userData.handlers.onPointerOver = () => {
    hovering = true;
    animateHover(true);
  };

  root.userData.handlers.onPointerOut = () => {
    hovering = false;
    pressing = false;
    animateHover(false);
  };

  root.userData.handlers.onPointerDown = () => {
    pressing = true;
    activeTweens.push(
      gsap.to(cardGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
    );
  };

  root.userData.handlers.onPointerUp = () => {
    pressing = false;
    killCardTweens();
    const scale = hovering ? 1.02 : 1.0;
    activeTweens.push(
      gsap.to(cardGroup.scale, { x: scale, y: scale, z: scale, duration: 0.2, ease: 'power2.out' })
    );
    if (hovering) {
      ctx.emit('hub-journal.select', { id: config.id });
    }
  };

  root.userData.handlers.onClick = () => {
    ctx.emit('hub-journal.select', { id: config.id });
  };

  root.userData.cleanup = () => {
    activeTweens.forEach((t) => t.kill());
    killCardTweens();
    backGeo.dispose();
    edgeGeo.dispose();
    cardGeo.dispose();
    backMat.dispose();
    edgeMat.dispose();
    cardMat.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
